package com.example.assets_management.security.rbac.audit; import com.example.assets_management.security.context.CurrentUserService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.UUID; @Service @RequiredArgsConstructor public class SecurityAuditServiceImpl implements SecurityAuditService { private final SecurityAuditLogRepository repo; private final CurrentUserService current; public void record(UUID companyId,UUID actor,UUID target,UUID role,UUID permission,SecurityAuditEventType type,String oldValue,String newValue){ SecurityAuditLog l=new SecurityAuditLog(); l.setCompanyId(companyId); l.setActorUserId(actor!=null?actor:(current.isAuthenticated()?current.requireUserId():null)); l.setTargetUserId(target); l.setRoleId(role); l.setPermissionId(permission); l.setEventType(type); l.setOldValue(oldValue); l.setNewValue(newValue); repo.save(l); } }
